/**
 * The sound effects service on expo-audio (works in Expo Go and on the web build). The sounds are generated by tools/make-sfx.ts into
 * assets/sfx/. Every sound is preloaded into a small pool of players so overlapping plays work; each sound has a runtime volume trim,
 * a slight random pitch for repeated sounds, and a rate limit so hundreds of shots per second never turn into hundreds of sounds.
 * expo-audio is loaded lazily on first use and never under Jest, so the store tests stay silent and fast. Never throws: a failure is
 * logged once and the game carries on without that sound.
 * Owner of this file: the "audio" agent.
 */
import type { AudioPlayer } from 'expo-audio';

import type { AudioService, SfxId } from './types';

interface SfxSpec {
  /** Players kept for this sound: how many copies can overlap. */
  pool: number;
  /** Runtime trim, 0..1. The mix itself is baked into the files (tools/make-sfx.ts, PEAK). */
  volume: number;
  /** Rate limit: at most this many starts per second. */
  maxPerSec: number;
  /** Random playback rate spread (± fraction): 0.06 = up to 6 % higher or lower in pitch. */
  vary: number;
}

const SPEC: Record<SfxId, SfxSpec> = {
  shot: { pool: 4, volume: 1, maxPerSec: 10, vary: 0.08 },
  hit: { pool: 4, volume: 1, maxPerSec: 12, vary: 0.06 },
  rim: { pool: 3, volume: 1, maxPerSec: 8, vary: 0.07 },
  floor: { pool: 3, volume: 1, maxPerSec: 8, vary: 0.1 },
  buy: { pool: 2, volume: 1, maxPerSec: 8, vary: 0 },
  roundEnd: { pool: 1, volume: 1, maxPerSec: 1, vary: 0 },
  newBest: { pool: 1, volume: 1, maxPerSec: 1, vary: 0 },
  footsteps: { pool: 1, volume: 1, maxPerSec: 1, vary: 0 },
  error: { pool: 1, volume: 1, maxPerSec: 4, vary: 0 },
  cheer: { pool: 2, volume: 1, maxPerSec: 0.25, vary: 0.04 },
};

const IDS = Object.keys(SPEC) as SfxId[];

/** Static requires so Metro bundles the files; only called when sound is first needed. */
function sources(): Record<SfxId, number> {
  return {
    shot: require('../../assets/sfx/shot.wav'),
    hit: require('../../assets/sfx/hit.wav'),
    rim: require('../../assets/sfx/rim.wav'),
    floor: require('../../assets/sfx/floor.wav'),
    buy: require('../../assets/sfx/buy.wav'),
    roundEnd: require('../../assets/sfx/roundEnd.wav'),
    newBest: require('../../assets/sfx/newBest.wav'),
    footsteps: require('../../assets/sfx/footsteps.wav'),
    error: require('../../assets/sfx/error.wav'),
    cheer: require('../../assets/sfx/cheer.wav'),
  };
}

interface Pool {
  players: AudioPlayer[];
  /** Whether each player has been started before (then it must seek back to 0 first). */
  used: boolean[];
  next: number;
  lastAt: number;
}

const underJest = typeof process !== 'undefined' && process.env?.JEST_WORKER_ID !== undefined;

let enabled = true;
let broken = underJest;
let pools: Partial<Record<SfxId, Pool>> | null = null;
let warned = false;

function warnOnce(err: unknown): void {
  if (warned) return;
  warned = true;
  console.warn('audio unavailable', err);
}

/** Creates every player once. Sets the session to mix with the player's own music and to respect the silent switch. */
function load(): Partial<Record<SfxId, Pool>> | null {
  if (pools || broken) return pools;
  try {
    const mod = require('expo-audio') as typeof import('expo-audio');
    mod.setAudioModeAsync({ playsInSilentMode: false, interruptionMode: 'mixWithOthers' }).catch(warnOnce);
    const src = sources();
    const made: Partial<Record<SfxId, Pool>> = {};
    for (const id of IDS) {
      const spec = SPEC[id];
      const players: AudioPlayer[] = [];
      for (let i = 0; i < spec.pool; i++) {
        const p = mod.createAudioPlayer(src[id]);
        p.volume = spec.volume;
        // Rate changes shift the pitch (varispeed) instead of stretching time.
        p.shouldCorrectPitch = false;
        players.push(p);
      }
      made[id] = { players, used: players.map(() => false), next: 0, lastAt: -Infinity };
    }
    pools = made;
  } catch (err) {
    broken = true;
    warnOnce(err);
  }
  return pools;
}

function start(pool: Pool, spec: SfxSpec): void {
  // Prefer an idle player, starting from the round-robin position; if all are busy, restart the oldest.
  const n = pool.players.length;
  let index = pool.next;
  for (let k = 0; k < n; k++) {
    const i = (pool.next + k) % n;
    if (!pool.players[i]?.playing) {
      index = i;
      break;
    }
  }
  pool.next = (index + 1) % n;
  const player = pool.players[index];
  if (!player) return;
  if (spec.vary > 0) player.setPlaybackRate(1 + (Math.random() * 2 - 1) * spec.vary);
  if (!pool.used[index]) {
    pool.used[index] = true;
    player.play();
    return;
  }
  // A finished player sits at its end: seek back first, then play (playing first could pause again at the end before the seek lands).
  player
    .seekTo(0)
    .then(() => {
      if (enabled) player.play();
    })
    .catch(warnOnce);
}

export const expoAudio: AudioService = {
  play(id) {
    if (!enabled || broken) return;
    try {
      const pool = load()?.[id];
      if (!pool) return;
      const spec = SPEC[id];
      const now = Date.now();
      if (now - pool.lastAt < 1000 / spec.maxPerSec) return;
      pool.lastAt = now;
      start(pool, spec);
    } catch (err) {
      warnOnce(err);
    }
  },
  setEnabled(on) {
    enabled = on;
    if (broken) return;
    try {
      if (on) {
        load();
        return;
      }
      if (!pools) return;
      for (const id of IDS) for (const p of pools[id]?.players ?? []) if (p.playing) p.pause();
    } catch (err) {
      warnOnce(err);
    }
  },
};
